const hoy = $('Calcular hoy').first().json.hoy;
const ventas = $('Ventas de hoy').all().map(i => i.json);
const abonos = $('Abonos de hoy').all().map(i => i.json);
const apartados = $('Apartados activos').all().map(i => i.json);

const sumar = (items) => items.reduce((s, r) => s + Number(r.importe || 0), 0);
const totalVentas = sumar(ventas);
const totalAbonos = sumar(abonos);
const totalHoy = totalVentas + totalAbonos;

const formas = ['efectivo','tarjeta','bizum'];
const porForma = (items) => formas.reduce((acc, f) => {
  acc[f] = items.filter(r => String(r.forma_pago||'').toLowerCase() === f).reduce((s,r)=>s+Number(r.importe||0),0);
  return acc;
}, {});
const vForma = porForma(ventas);
const aForma = porForma(abonos);

const limite = new Date(hoy + 'T00:00:00');
limite.setDate(limite.getDate() + 7);
const proximos = apartados
  .filter(a => a.fecha_limite && new Date(a.fecha_limite + 'T00:00:00') >= new Date(hoy + 'T00:00:00') && new Date(a.fecha_limite + 'T00:00:00') <= limite)
  .sort((a,b) => String(a.fecha_limite).localeCompare(String(b.fecha_limite)));

const pendienteTotal = apartados.reduce((s,a) => s + Number(a.pendiente || 0), 0);

const fmt = (n) => Number(n).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' \u20ac';
const fechaCorta = (f) => String(f).split('-').reverse().join('/');

const filas = proximos.map(a =>
  '<tr><td>' + a.cliente + '</td><td>' + a.producto + ' ' + (a.talla||'') + '</td><td>' + fmt(a.pendiente) + '</td><td>' + fechaCorta(a.fecha_limite) + '</td></tr>'
).join('');

const html = '<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panel Marisa</title>'
+ '<style>body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f7f7f7;color:#222}.card{background:#fff;border-radius:12px;padding:16px;margin-bottom:16px;box-shadow:0 2px 6px rgba(0,0,0,.08)}h1{font-size:20px;margin:0 0 8px}h2{font-size:16px;margin:0 0 8px;color:#555}.big{font-size:28px;font-weight:700;color:#1a7f37}.row{display:flex;justify-content:space-between;padding:4px 0;border-bottom:1px solid #eee}.table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:8px 4px;border-bottom:1px solid #eee;text-align:left}th{color:#555;font-weight:600}.empty{color:#888;font-style:italic;padding:8px 0}</style>'
+ '</head><body>'
+ '<div class="card"><h1>Panel de Marisa</h1><p style="margin:0;color:#888;font-size:13px">Actualizado: ' + fechaCorta(hoy) + '</p></div>'
+ '<div class="card"><h2>Cobrado hoy</h2><div class="big">' + fmt(totalHoy) + '</div>'
+ '<div class="row"><span>Ventas directas</span><span>' + fmt(totalVentas) + '</span></div>'
+ '<div class="row"><span>Abonos de apartados</span><span>' + fmt(totalAbonos) + '</span></div>'
+ '<div class="row"><span>Efectivo</span><span>' + fmt(vForma.efectivo + aForma.efectivo) + '</span></div>'
+ '<div class="row"><span>Tarjeta</span><span>' + fmt(vForma.tarjeta + aForma.tarjeta) + '</span></div>'
+ '<div class="row"><span>Bizum</span><span>' + fmt(vForma.bizum + aForma.bizum) + '</span></div>'
+ '</div>'
+ '<div class="card"><h2>Apartados por vencer (7 dias)</h2>'
+ (proximos.length ? '<table class="table"><thead><tr><th>Cliente</th><th>Producto</th><th>Pendiente</th><th>Limite</th></tr></thead><tbody>' + filas + '</tbody></table>' : '<div class="empty">No hay apartados proximos a vencer.</div>')
+ '</div>'
+ '<div class="card"><h2>Total pendiente de cobro</h2><div class="big">' + fmt(pendienteTotal) + '</div><p style="margin:4px 0 0;color:#888;font-size:13px">' + apartados.length + ' apartados activos</p></div>'
+ '</body></html>';

return [{ json: { html } }];
